<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {blankRule,copy,emptyInput,inputValid,validMonth,validRule} from '../payrollUi'
import {wageEvidenceValid} from '../annualWages'
import type {SupplementalProposal} from '../supplemental'
import SupplementalProposalFields from './SupplementalProposalFields.vue'
import {storeToday} from '../time'
import type {PayChange,ChangeWrite,ChangeProfileWrite,ChangeMonthDraft} from '../payChanges'
import type {PayProfile,SalaryTemplate,LineInput,PrDocument} from '../payrollTypes'
import type {TemplateAdoption} from '../payTemplatePublication'
import type {Option} from '../types'
import PayRuleFields from './PayRuleFields.vue'
import PayChangeProfileFields from './PayChangeProfileFields.vue'
import PayChangeMonthFields from './PayChangeMonthFields.vue'
const props=defineProps<{request:PayChange|null;seed?:ChangeWrite;companyId:string;salaryAccess:boolean;birthDates:Record<string,string>;prDocuments:Record<string,PrDocument[]>;employees:Option[];profiles:PayProfile[];templates:SalaryTemplate[];adoptions:TemplateAdoption[];scheduledDates:Record<string,string>;busy:boolean}>(),emit=defineEmits<{save:[id:string,body:ChangeWrite];cancel:[]}>()
const {english,api,current,message,r}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
const id=props.request?.id||crypto.randomUUID(),kind=ref(props.seed?(props.seed.profile?'profile':'monthly'):props.request?.adoptionId?'derived':props.request&&!props.request.content.profile?'monthly':props.salaryAccess?'profile':'derived'),employee=ref(props.seed?.employeeId||props.request?.employeeId||''),effective=ref(props.seed?.effectiveDate||props.request?.effectiveDate||storeToday()),reason=ref(props.seed?props.seed.reason:props.request?.content.reason||''),adoptionId=ref(props.request?.adoptionId||''),derived=ref(copy(props.request?.content.derivedRule||blankRule())),profile=ref<ChangeProfileWrite|null>(null),months=ref<ChangeMonthDraft[]>(props.request?.content.months.map(m=>({month:m.month,input:{...copy(m.after),version:m.before.version},loaded:true,loading:false,error:'',fixed:true}))||[]),error=ref('')
const supplemental=ref<SupplementalProposal[]>(copy(props.seed?.supplemental||props.request?.content.supplemental||[]))
const existing=computed(()=>props.profiles.filter(p=>p.employeeId===employee.value&&p.effectiveFrom<=effective.value).sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom))[0]),adoption=computed(()=>props.adoptions.find(a=>a.id===adoptionId.value))
const prConfirmed=ref(false),employeePrDocuments=computed(()=>props.prDocuments[employee.value]||[]),selectedPrDocument=computed(()=>employeePrDocuments.value.find(d=>d.id===profile.value?.cpf.prDocumentId))
watch(()=>[employee.value,profile.value?.cpf.citizenship,profile.value?.cpf.prDocumentId,selectedPrDocument.value?.prEffectiveOn],()=>{prConfirmed.value=false},{flush:'sync'})
function fromProfile(p:PayProfile):ChangeProfileWrite{return {expectedVersion:props.profiles.find(v=>v.employeeId===employee.value&&v.effectiveFrom===effective.value)?.version||0,companyId:props.companyId,employeeId:employee.value,effectiveFrom:effective.value,templateId:p.templateId,expectedTemplateVersion:props.templates.find(t=>t.id===p.templateId)?.version||p.templateVersion,rule:copy(p.rule),cpf:{...copy(p.cpf),birthDate:props.birthDates[employee.value]||p.cpf.birthDate},payment:copy(p.payment||null),cdac:copy(p.cdac||null)}}
function resetProfile(){profile.value=existing.value?fromProfile(existing.value):null}
watch(employee,()=>{if(!props.request){resetProfile();months.value=[];supplemental.value=[]}})
watch(effective,date=>{if(props.request)return;if(profile.value){profile.value.effectiveFrom=date;profile.value.expectedVersion=props.profiles.find(p=>p.employeeId===employee.value&&p.effectiveFrom===date)?.version||0}else resetProfile()})
if(props.request?.content.profile)profile.value=fromProfile(props.request.content.profile)
if(props.seed){profile.value=copy(props.seed.profile);months.value=props.seed.months.map(m=>({month:m.month,input:{...copy(m.input),employeeId:props.seed!.employeeId!,version:m.input.expectedVersion},loaded:true,loading:false,error:'',fixed:true}))}
function templateChanged(event:Event){const t=props.templates.find(t=>t.id===(event.target as HTMLSelectElement).value);if(!t)return;const old=profile.value;profile.value={expectedVersion:props.profiles.find(v=>v.employeeId===employee.value&&v.effectiveFrom===effective.value)?.version||0,companyId:props.companyId,employeeId:employee.value,effectiveFrom:effective.value,templateId:t.id,expectedTemplateVersion:t.version,rule:copy(t.rule),cpf:copy(old?.cpf||{citizenship:'citizen',birthDate:props.birthDates[employee.value]||null,prDate:null,prMode:'GG',electionReference:''}),payment:copy(old?.payment||null),cdac:copy(old?.cdac||null)}}
const baselineRevisions=new WeakMap<ChangeMonthDraft,number>()
async function baseline(m:ChangeMonthDraft){const rev=(baselineRevisions.get(m)||0)+1;baselineRevisions.set(m,rev);m.loaded=false;m.error='';if(!validMonth(m.month))return;const month=m.month,subject=employee.value;m.loading=true;try{const input=await api().get<LineInput>(`/pay-change-monthly-baseline?companyId=${props.companyId}&employeeId=${subject}&month=${month}`);if(current()&&baselineRevisions.get(m)===rev&&months.value.includes(m)&&m.month===month&&employee.value===subject){m.input=copy(input);m.loaded=true}}catch(e){if(current()&&baselineRevisions.get(m)===rev&&months.value.includes(m)&&m.month===month)m.error=message(e)}finally{if(baselineRevisions.get(m)===rev&&m.month===month)m.loading=false}}
function selectAdoption(){if(adoption.value){derived.value=copy(adoption.value.rule);const date=props.scheduledDates[adoption.value.id];if(date&&effective.value<date)effective.value=date}}
function save(){error.value='';if(supplemental.value.length&&(kind.value==='derived'||!employee.value||supplemental.value.some(p=>!validMonth(p.originMonth)||!validMonth(p.settlementMonth)||p.settlementMonth<p.originMonth||!p.source.snapshotHash||!p.evidenceReference.trim()||!p.items.length||p.items.some(i=>i.kind!=='wage_event'||!i.label.trim()||!/^\d{1,8}(\.\d{1,2})?$/.test(i.amount)||Number(i.amount)<=0||!wageEvidenceValid(i.eventEvidence,true)||i.eventEvidence?.contributionMonth!==p.originMonth||i.eventEvidence?.settlementMonth!==p.settlementMonth)))){error.value=x('请核对补发来源、正额项目、事项日期和原贡献月／结算月。','Review supplemental sources, positive amounts, event dates and contribution / settlement months.');return}const cpf=kind.value==='profile'?profile.value?.cpf:null;if(cpf?.citizenship==='spr'){if(cpf.prDocumentId&&(!selectedPrDocument.value||cpf.prDate!==selectedPrDocument.value.prEffectiveOn)){error.value=r('prDocumentReview');return}if(cpf.prDocumentId&&!prConfirmed.value){error.value=r('prDocumentRequired');return}if(!cpf.prDate){error.value=r('invalid');return}}if(!reason.value.trim()||!effective.value||(kind.value==='derived'?(!adoption.value||!validRule(derived.value)||(props.scheduledDates[adoptionId.value]||'')>effective.value):(!employee.value||kind.value==='profile'&&(!profile.value||!validRule(profile.value.rule))||kind.value==='monthly'&&!months.value.length&&!supplemental.value.length))||kind.value!=='derived'&&(months.value.some(m=>!m.loaded||m.loading||!validMonth(m.month)||!inputValid(m.input))||new Set(months.value.map(m=>m.month)).size!==months.value.length)){error.value=x('请核对主体、理由、有效日期、规则和不重复的月份。','Check subject, reason, effective date, rules and unique months.');return}const p=kind.value==='profile'&&profile.value?copy(profile.value):null;if(p){p.employeeId=employee.value;p.effectiveFrom=effective.value;if(p.cpf.citizenship!=='spr'){p.cpf.prDate=null;p.cpf.prDocumentId=null;p.cpf.prMode='GG';p.cpf.electionReference=''}}emit('save',id,{expectedRevision:props.request?.revision||0,companyId:props.companyId,employeeId:kind.value==='derived'?null:employee.value,effectiveDate:effective.value,adoptionId:kind.value==='derived'?adoptionId.value:null,profile:p,derivedRule:kind.value==='derived'?copy(derived.value):null,reason:reason.value.trim(),...(supplemental.value.length||props.request?.content.supplemental?.length?{supplemental:copy(supplemental.value)}:{}),months:kind.value==='derived'?[]:months.value.map(m=>({month:m.month,input:{expectedVersion:m.input.version,workingDays:m.input.workingDays||null,payableDays:m.input.payableDays||null,unitsReviewed:m.input.unitsReviewed,specialDaysReviewed:m.input.specialDaysReviewed,items:copy(m.input.items),note:m.input.note,cdacReview:m.input.cdacReview||null,cdacAutomatic:!m.input.cdacReview}}))})}
</script>
<template><form class="wf-section" @submit.prevent="save"><h3>{{x('申请草稿','Change draft')}}</h3><p class="wf-hint">{{x('保存和提交不会修改有效工资；待审／驳回期间继续使用原有效方案。首次原样采用或经济内容不变的免审资格由服务端判断。','Saving and submission leave effective pay unchanged. The server determines eligibility for initial unchanged adoption.')}}</p><fieldset :disabled="busy"><label>{{x('申请类型','Change type')}}<select v-model="kind" :disabled="!!request||!!seed" :aria-label="x('申请类型','Change type')"><option v-if="salaryAccess" value="profile">{{x('个人方案','Personal profile')}}</option><option v-if="salaryAccess" value="monthly">{{x('仅月度输入','Monthly inputs only')}}</option><option v-if="adoptions.length" value="derived">{{x('本店派生独立草稿','Independent store derivation')}}</option></select></label><template v-if="kind==='derived'"><p>{{x('只修改本店候选，母版和员工方案保持原状。','Creates a store candidate; master and employee profiles remain unchanged.')}}</p><label>{{x('本店采用','Store adoption')}}<select v-model="adoptionId" :aria-label="x('本店采用','Store adoption')" :disabled="!!request||!!seed" required @change="selectAdoption"><option value="">—</option><option v-for="a in adoptions" :key="a.id" :value="a.id">{{a.name}} · {{a.releaseVersion}} / {{a.storeVersion}} {{scheduledDates[a.id]?x('批准待生效','Approved future')+' '+scheduledDates[a.id]:''}}</option></select></label><PayRuleFields v-if="adoptionId" :rule="derived" :disabled="busy"/></template><template v-else><label>{{x('员工','Employee')}}<select v-model="employee" :aria-label="x('员工','Employee')" :disabled="!!request||!!seed" required><option value="">—</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><p>{{x('原有效方案','Current effective profile')}}: {{existing?.rule.rate||x('无方案；批准前阻断计算','Missing; computation blocked until approved')}} · {{existing?.effectiveFrom}}</p></template><p v-if="kind==='monthly'&&!supplemental.length" class="wf-hint">{{x('纯月度申请按所选月份由服务端定位有效方案与主体日期。','For monthly-only changes, the server resolves the effective profile and subject date from the selected month.')}}</p><label v-if="kind!=='monthly'||supplemental.length">{{x('生效日期','Effective date')}}<input v-model="effective" type="date" required :disabled="!!request||!!seed" :aria-label="x('生效日期','Effective date')"></label><template v-if="kind==='profile'&&employee"><label>{{x('方案来源模板','Source template')}}<select :value="profile?.templateId||''" @change="templateChanged"><option value="">—</option><option v-for="t in templates" :key="t.id" :value="t.id" :disabled="!t.enabled&&t.id!==profile?.templateId">{{t.name}} · {{t.version}}</option></select></label><PayChangeProfileFields v-if="profile" :profile="profile" :birth-date="birthDates[employee]" :pr-documents="employeePrDocuments" v-model:pr-confirmed="prConfirmed" :busy="busy"/></template><template v-if="kind!=='derived'&&employee"><button type="button" @click="months.push({month:'',input:emptyInput(employee),loaded:false,loading:false,error:'',fixed:false})">{{x('添加月份','Add month')}}</button><PayChangeMonthFields :months="months" :busy="busy" @remove="months.splice($event,1)" @baseline="baseline"/></template><SupplementalProposalFields v-if="salaryAccess&&kind!=='derived'&&employee" :proposals="supplemental" :company-id="companyId" :employee-id="employee" :disabled="busy"/><label>{{x('变更理由','Reason')}}<textarea v-model="reason" required maxlength="1000" :aria-label="x('变更理由','Reason')"/></label></fieldset><p v-if="error" role="alert">{{error}}</p><footer class="wf-form-actions"><button type="button" :disabled="busy" @click="emit('cancel')">{{x('取消','Cancel')}}</button><button class="primary" type="submit" :disabled="busy">{{x('保存申请草稿','Save change draft')}}</button></footer></form></template>
